chart.options:
chart: {
  type: 'dumbbell',
  height: 380
},
colors: ['#93C5FD', '#3B82F6', '#1D4ED8'],
title: {
  text: 'Share of teams running each stage in CI',
  align: 'left'
},
subtitle: {
  text: 'Three snapshots on one row. Only the two extremes are labelled.',
  align: 'left'
},
plotOptions: {
  bar: {
    dumbbell: {
      connector: {
        color: '#E5E7EB',
        opacity: 1
      },
      dataLabels: {
        formatter: function (val) {
          return val + '%'
        }
      }
    }
  }
},
xaxis: {
  min: 0,
  max: 100,
  labels: {
    formatter: function (val) {
      return val + '%'
    }
  }
}

